#!/usr/bin/env bash
set -euo pipefail

{cursor}

die() {
  printf 'error: %s\n' "$*" >&2
  exit 1
}

tmp="$(mktemp -d)"
cleanup() { rm -rf "$tmp"; }
trap cleanup EXIT

{cursor}

{cursor}() {
  local name="${1:?name required}"
  local greeting="${2:-hello}"

  printf '%s, %s!\n' "$greeting" "$name"
}

out=""
verbose=false

while getopts ":o:vh" opt; do
  case "$opt" in
    o) out="$OPTARG" ;;
    v) verbose=true ;;
    h) usage; exit 0 ;;
    :) die "option -$OPTARG needs a value" ;;
    \?) die "unknown option: -$OPTARG" ;;
  esac
done
shift $((OPTIND - 1))

{cursor}

for arg in "$@"; do
  {cursor}
done
